    15→/// Initialize a `BeaconState` from genesis data.
    16→pub fn initialize_beacon_state_from_eth1<E: EthSpec>(
    17→    eth1_block_hash: Hash256,
    18→    eth1_timestamp: u64,
    19→    deposits: Vec<Deposit>,
    20→    execution_payload_header: Option<ExecutionPayloadHeader<E>>,
    21→    spec: &ChainSpec,
    22→) -> Result<BeaconState<E>, BlockProcessingError> {
    23→    let genesis_time = eth2_genesis_time(eth1_timestamp, spec)?;
    24→    let eth1_data = Eth1Data {
    25→        // Temporary deposit root
    26→        deposit_root: Hash256::zero(),
    27→        deposit_count: deposits.len() as u64,
    28→        block_hash: eth1_block_hash,
    29→    };
    30→    let mut state = BeaconState::new(genesis_time, eth1_data, spec);
    31→
    32→    // Seed RANDAO with Eth1 entropy
    33→    state.fill_randao_mixes_with(eth1_block_hash)?;
    34→
    35→    let mut deposit_tree = DepositDataTree::create(&[], 0, DEPOSIT_TREE_DEPTH);
    36→
    37→    for deposit in deposits.into_iter() {
    38→        deposit_tree
    39→            .push_leaf(deposit.data.tree_hash_root())
    40→            .map_err(BlockProcessingError::MerkleTreeError)?;
    41→        state.eth1_data_mut().deposit_root = deposit_tree.root();
    42→        let Deposit { proof, data } = deposit;
    43→        apply_deposit(&mut state, data, Some(proof), true, spec)?;
    44→    }
    45→
    46→    process_activations(&mut state, spec)?;
    47→
    48→    // To support testnets with Altair enabled from genesis, perform a possible state upgrade here.
    49→    // This must happen *after* deposits and activations are processed or the calculation of sync
    50→    // committees during the upgrade will fail. It's a bit cheeky to do this instead of having
    51→    // separate Altair genesis initialization logic, but it turns out that our
    52→    // use of `BeaconBlock::empty` in `BeaconState::new` is sufficient to correctly initialise
    53→    // the `latest_block_header` as per:
    54→    // https://github.com/ethereum/eth2.0-specs/pull/2323
    55→    if spec
    56→        .altair_fork_epoch
    57→        .is_some_and(|fork_epoch| fork_epoch == E::genesis_epoch())
    58→    {
    59→        upgrade_to_altair(&mut state, spec)?;
    60→
    61→        state.fork_mut().previous_version = spec.altair_fork_version;
    62→    }
    63→
    64→    // Similarly, perform an upgrade to the merge if configured from genesis.
    65→    if spec
    66→        .bellatrix_fork_epoch
    67→        .is_some_and(|fork_epoch| fork_epoch == E::genesis_epoch())
    68→    {
    69→        // this will set state.latest_execution_payload_header = ExecutionPayloadHeaderBellatrix::default()
    70→        upgrade_to_bellatrix(&mut state, spec)?;
    71→
    72→        // Remove intermediate Altair fork from `state.fork`.
    73→        state.fork_mut().previous_version = spec.bellatrix_fork_version;
